--- _headers
# Cloudflare Workers static assets: response headers for the site.
# https://developers.cloudflare.com/workers/static-assets/headers/
#
# The app is a single-purpose Workers site with no third-party script: the only
# cross-origin resources are swisstopo tiles/images and e-rara IIIF images, and
# every fetch goes through the same-origin /api/* Worker proxy.

/*
  X-Content-Type-Options: nosniff
  Referrer-Policy: strict-origin-when-cross-origin
  X-Frame-Options: SAMEORIGIN
  Permissions-Policy: geolocation=(), camera=(), microphone=(), payment=()
  Content-Security-Policy: default-src 'self'; base-uri 'self'; form-action 'self'; frame-ancestors 'self'; object-src 'none'; script-src 'self'; style-src 'self' 'unsafe-inline'; font-src 'self'; img-src 'self' data: blob: https://www.e-rara.ch https://wmts.geo.admin.ch https://api3.geo.admin.ch https://map.geo.admin.ch; connect-src 'self'

# Fonts never change under the same file name: cache them hard.
/fonts/*
  Cache-Control: public, max-age=31536000, immutable

# App code and styles change during development: short cache, revalidate often.
/app/*
  Cache-Control: public, max-age=300
/styles/*
  Cache-Control: public, max-age=300

# Data files are regenerated by scripts/harvest-seed.mjs: keep them fresh.
/data/*
  Cache-Control: public, max-age=600

/*!
 * App layout – Kartenzeit (historical map explorer).
 * Composition only; visual language comes from the canton tokens/components.
 */

.app-main {
  padding-block: var(--zh-size-large) 0;
}

.app-intro {
  background: var(--zh-white);
  border: 1px solid var(--zh-color-border);
  padding: var(--zh-size-large) var(--zh-size-regular);
  margin-bottom: var(--zh-size-large);
}

.app-intro p {
  margin-bottom: var(--zh-size-small-regular);
}

/* The “read more” link only matters where the lead paragraph is clamped. */
.app-intro__more {
  display: none;
}

/* Facts strip: cantonal “chapter number” rhythm — value first, label under it. */
.zh-facts {
  display: flex;
  flex-wrap: wrap;
  gap: var(--zh-size-large);
  margin: 0 0 var(--zh-size-regular);
  padding: 0 0 var(--zh-size-small-regular);
  list-style: none;
  border-bottom: 1px solid var(--zh-color-border);
}

.zh-facts li {
  display: flex;
  flex-direction: column-reverse;
  gap: 2px;
}

.zh-facts__value {
  font-family: var(--zh-font-black);
  font-size: var(--zh-font-medium);
  font-weight: 900;
  letter-spacing: -0.01em;
}

.zh-facts__term {
  font-size: var(--zh-font-tiny);
  color: var(--zh-color-text-soft);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.zh-check-field {
  margin-bottom: var(--zh-size-large);
}

.app-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--zh-size-small-regular);
  padding: var(--zh-size-small-regular) var(--zh-size-regular);
  background: var(--zh-black-5);
  border-top: var(--zh-rule) solid var(--zh-black);
  margin-bottom: var(--zh-size-regular);
}

.app-toolbar__group {
  display: flex;
  align-items: center;
  gap: var(--zh-size-tiny);
}

.app-toolbar__label {
  font-family: var(--zh-font-black);
  font-size: var(--zh-font-bigger-regular);
  font-weight: 900;
}

.app-toolbar .zh-label {
  margin: 0;
}

.app-toolbar .zh-select {
  width: auto;
  min-height: var(--zh-size-big);
  font-size: var(--zh-font-small);
}

/* ---- View switch: list only / map only / split ---- */
.app-grid {
  display: grid;
  gap: var(--zh-column-gap);
  align-items: start;
}

/* Single-column layouts (phones and tablets) put the map first: a map explorer
   whose map sits below a 40-entry result list is unusable on a phone. The DOM
   order stays list-first for screen readers and the tab order, and the map
   keeps its own keyboard controls. */
@media (max-width: 1023px) {
  .app-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .app-mapwrap {
    order: -1;
  }
}

.app-view--map .app-grid {
  grid-template-columns: minmax(0, 1fr);
}

.app-view--map .app-side {
  display: none;
}

.app-view--map .app-map,
.app-view--map .app-mapwrap {
  position: static;
  height: min(78vh, 760px);
}

.app-view--list .app-grid {
  grid-template-columns: minmax(0, 1fr);
}

.app-view--list .app-mapwrap,
.app-view--list .app-map__skip,
.app-view--list .app-map__hint {
  display: none;
}

.app-view--list .app-result-list {
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));

  font: inherit;
}

/* ---- Small screens: keep the way to the map short ---- */
.zh-header__note-short {
  display: none;
}

@media (max-width: 599px) {
  /* The long disclaimer lives in the footer and the “Über das Projekt”
     section; the top bar only needs the design reference on a phone. */
  .zh-header__note-long {
    display: none;
  }
  .zh-header__note-short {
    display: inline;
  }
  .zh-header__main {
    padding-block: var(--zh-size-small-regular);
    gap: var(--zh-size-tiny);
  }
  .app-main {
    padding-block: var(--zh-size-small-regular) 0;
  }
  .app-intro {
    padding: var(--zh-size-small-regular) var(--zh-size-regular);
    margin-bottom: var(--zh-size-small-regular);
  }
  /* Cantonal type curve for h1 at the smallest breakpoint ($fontSizeCurves
     huge/tiny = 28px) — the 32px base is meant for ≥400px. */
  .app-intro .zh-heading--1 {
    font-size: var(--zh-font-small-big);
    margin-bottom: var(--zh-size-tiny);
  }
  /* Orientation text stays readable but does not push the map off the screen;
     the full wording lives in “Über das Projekt” and the result list. */
  .app-intro .zh-lead {
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
    margin-bottom: var(--zh-size-tiny);
  }
  .app-intro__more {
    display: block;
    margin: 0 0 var(--zh-size-tiny);
    font-size: var(--zh-font-small);
  }
  .zh-facts {
    gap: var(--zh-size-regular) var(--zh-size-large);
  }
  /* Quick picks (search) and quick year ranges stay on one scrollable line
     instead of wrapping into a tall block above the map. */
  #place-quick,
  .zh-quickranges {
    flex-wrap: nowrap;
    overflow-x: auto;
    scrollbar-width: thin;
    padding-bottom: 2px;
  }
  #place-quick > *,
  .zh-quickranges > * {
    flex: 0 0 auto;
  }
}

/* ---------- year histogram (module: public/app/results.js, maps-2) ----
   Bars are real buttons (one per decade) in a toolbar pattern: Tab reaches the
   chart once, ArrowLeft/Right/Home/End move between decades, Enter filters.
   Height is the share of the busiest decade, so 0-record decades keep a 2px
   baseline and stay focusable. */
.zh-histogram {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  block-size: 56px;
  margin-block: var(--zh-size-tiny) calc(var(--zh-size-tiny) / 2);
  padding-block-end: 2px;
  border-block-end: 1px solid var(--zh-color-border-strong);
}

.zh-histogram__bin {
  flex: 1 1 0;
  display: flex;
  align-items: flex-end;
  min-inline-size: 6px;
  block-size: 100%;
  padding: 0;
  border: 0;
  /* The tinted column is what makes the selected decades visible even when the
     bar of that decade is only 2 px tall (0–2 records). */
  background: none;
  cursor: pointer;
}

.zh-histogram__bin[aria-current='true'] {
  background: var(--zh-color-bg);
}

.zh-histogram__bar {
  display: block;
  inline-size: 100%;
  min-block-size: 2px;
  background: var(--zh-color-accent);
  opacity: 0.5;
  border-radius: var(--zh-radius) var(--zh-radius) 0 0;
  transition: opacity 120ms ease-out;
}

.zh-histogram__bin:hover .zh-histogram__bar,
.zh-histogram__bin:focus-visible .zh-histogram__bar {
  opacity: 1;
}

.zh-histogram__bin[aria-current='true'] .zh-histogram__bar {
  opacity: 1;
  background: var(--zh-color-accent-dark);
}

.zh-histogram__scale {
  display: flex;
  justify-content: space-between;
  margin: 0 0 var(--zh-size-tiny);
  color: var(--zh-color-text-soft);
  font-size: var(--zh-font-small);
  font-variant-numeric: tabular-nums;
}

