      { label: 'sheet thumbnails', timeout: 20_000 },
    );
  } catch {
    thumbs = await cdp.eval(`(() => { const imgs = [...document.querySelectorAll('#page-strip img')]; return { loaded: imgs.filter((img) => img.naturalWidth > 0).length, total: imgs.length }; })()`);
